import{z as B,x as n,o as r,c as p,q as o,j as A,D as e,d as t,s,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"每层成本与每晶圆成本","description":"","frontmatter":{"title":"每层成本与每晶圆成本","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cost-per-layer-wafer.md","filePath":"litho/cost-per-layer-wafer.md","lastUpdated":1791063341000}'),d={name:"litho/cost-per-layer-wafer.md"};function h(D,E,m,c,u,f){const l=n("Mermaid");return r(),p("div",null,[E[2]||(E[2]=o('<h1 id="每层成本与每晶圆成本" tabindex="-1">每层成本与每晶圆成本 <a class="header-anchor" href="#每层成本与每晶圆成本" aria-label="Permalink to &quot;每层成本与每晶圆成本&quot;">​</a></h1><div class="epigraph"><p>晶圆成本是各层光刻–刻蚀–薄膜之和再加测试；比较 EUV 与多重必须按层加总，不能按「用没用 EUV」一句话。</p><footer>—— 对照晶圆成本结构与 per-layer litho cost 的产业讨论；不编造美元表</footer></div><p><a href="/litho/irds-roadmap">上一课</a>给出需求骨架。缺口是钱。本课钉每层成本与每晶圆成本。EUV 与多重的交叉点，留给<a href="/litho/euv-vs-multipattern-cost-crossover">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一层成本 ≈ 扫描机折旧与维护 + 轨道化学 + 掩模摊销 + 计量 + 重工税 + 刻蚀/薄膜若算进「图形化模块」。EUV 层：光源、pellicle、剂量时间、抗蚀剂、掩模更贵，但张数可能更少。浸没多重：扫描机便宜些，过机次数、套刻、掩模张数把模块成本抬上去。晶圆成本还含非光刻（注入、CMP、清洗）。</p><p>缺口是<strong>按层模块账</strong>，不是节点名。不引用无来源的「EUV 晶圆 xx 美元」。</p><h3 id="掩模摊销随片量" tabindex="-1">掩模摊销随片量 <a class="header-anchor" href="#掩模摊销随片量" aria-label="Permalink to &quot;掩模摊销随片量&quot;">​</a></h3><p>工程 lot 掩模主导；量大后扫描机与胶主导。<a href="/litho/mask-cost-cycle">掩模成本</a> 已写。本课把它嵌进每晶圆。</p><p><span class="marginnote">wph 是单次过机。LELE 模块有效产能是 wph 除以次数再扣轨道刻蚀节拍。用标称 wph 去除以晶圆成本会乐观。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建层表：每层曝光策略、过机次数、掩模数、计量密度。求和。灵敏度：剂量、pellicle 透过、重工率。与良率：低良率把所有成本摊到好片上，往往超过省一次曝光的钱。</p><p>同一层选不同策略，钱会流进不同的口袋：EUV 把单价押在光源、胶与掩模上，浸没多重把单价摊到过机次数、套刻与掩模张数上。比较就必须把两列各自的口袋都掏空算总账。</p>',12)),(r(),A(i,null,{default:e(()=>[s(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20EUV%5B%22EUV%20%E5%8D%95%E6%AC%A1%E5%9B%BE%E5%BD%A2%E5%8C%96%E6%A8%A1%E5%9D%97%22%5D%0A%20%20%20%20E1%5B%22EUV%20%E6%89%AB%E6%8F%8F%E6%9C%BA%E6%8A%98%E6%97%A7%E4%B8%8E%E7%BB%B4%E6%8A%A4%22%5D%20--%3E%20ES%5B%22%E6%A8%A1%E5%9D%97%E6%80%BB%E6%88%90%E6%9C%AC%22%5D%0A%20%20%20%20E2%5B%22EUV%20%E6%8E%A9%E6%A8%A1%E4%B8%8E%20pellicle%20%E6%91%8A%E9%94%80%22%5D%20--%3E%20ES%0A%20%20%20%20E3%5B%22EUV%20%E4%B8%93%E7%94%A8%E8%83%B6%E4%B8%8E%E5%89%82%E9%87%8F%E6%97%B6%E9%97%B4%22%5D%20--%3E%20ES%0A%20%20end%0A%20%20subgraph%20IMP%5B%22%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%20LELE%20%E6%A8%A1%E5%9D%97%22%5D%0A%20%20%20%20I1%5B%22%E6%B5%B8%E6%B2%A1%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%B0%8F%E6%97%B6%20%C3%97%20%E8%BF%87%E6%9C%BA%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20IS%5B%22%E6%A8%A1%E5%9D%97%E6%80%BB%E6%88%90%E6%9C%AC%22%5D%0A%20%20%20%20I2%5B%22%E6%8E%A9%E6%A8%A1%E5%BC%A0%E6%95%B0%20%C3%97%202%20%E4%BB%A5%E4%B8%8A%E6%91%8A%E9%94%80%22%5D%20--%3E%20IS%0A%20%20%20%20I3%5B%22%E5%A5%97%E5%88%BB%E8%AE%A1%E9%87%8F%E4%B8%8E%E9%87%8D%E5%B7%A5%E7%A8%8E%22%5D%20--%3E%20IS%0A%20%20end%0A%20%20ES%20--%3E%20W%5B%22%E6%AF%8F%E6%99%B6%E5%9C%86%E6%88%90%E6%9C%AC%E6%B1%82%E5%92%8C%22%5D%0A%20%20IS%20--%3E%20W%0A%20%20Y%5B%22%E8%89%AF%E7%8E%87%E5%88%86%E6%91%8A%E5%88%B0%E5%A5%BD%E7%89%87%22%5D%20--%3E%20W%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：wph（wafers per hour）是扫描机每小时过机的晶圆片数，是产能的标称尺。「重工税」指一层返工重做——白烧一次过机、一套化学品和一段机时，像给这层额外交一笔税；重工率每抬几个百分点，模块成本跟着线性涨。")],-1)),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例：掩模摊销随片量摊薄。设一套掩模贵 \\(100\\)（单位任选）：工程批只流 \\(50\\) 片，每片摊 \\(2\\)；量产流 \\(5\\) 万片，每片只摊 \\(0.002\\)，差一千倍。所以工程 lot 掩模主导成本，量大后瓶颈转到扫描机小时与胶——这与「掩模摊销随片量」一节互为注脚。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"成本随步骤数近线性（机会缺陷也近线性增加机会），随随机剂量近超线性（wph 掉）。交叉点课将用这张结构，仍不填假数字。",-1)),(r(),A(i,null,{default:e(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%90%84%E5%B1%82%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%20--%3E%20W%5B%22%E6%AF%8F%E6%99%B6%E5%9C%86%22%5D%0A%20%20Y%5B%22%E8%89%AF%E7%8E%87%22%5D%20--%3E%20GOOD%5B%22%E6%AF%8F%E5%A5%BD%E7%89%87%22%5D%0A%20%20W%20--%3E%20GOOD%0A%20%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E6%91%8A%E9%94%80%22%5D%20--%3E%20L%0A%20%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E5%B0%8F%E6%97%B6%22%5D%20--%3E%20L%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=o('<p><span class="marginnote">直觉类比：每晶圆成本像餐厅后厨的账单——每层是一道菜（光刻、刻蚀、薄膜各收一次钱），而良率是最后按「完整上桌的菜」分摊：报废的盘子照样花了料钱，洒得越多，每只好盘越贵。这就是低良率常常吃掉省一次曝光所省下全部钱的直觉版本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给美元。不把测试、封装算进本课除非声明。成本不自动等于价格。</p><p>后课默认：比较必须按层模块；下一课专门画 EUV 单次 vs DUV 多重的交叉逻辑。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每晶圆 = 层模块之和；图形化模块含掩模、过机、计量、重工。</li><li>标称 wph 必须除过机次数。</li><li>良率把成本摊到好片，常主导。</li><li>出处：per-layer litho cost 产业讨论结构；无来源报价不用。</li></ul>',6))])}const V=B(d,[["render",h]]);export{_ as __pageData,V as default};
